<x-seller-verification.layout :seller="$seller">
    <h2 class="h4">Seller application summary</h2><p class="text-muted">Review the information SmartBasket has on file. Sensitive values are masked.</p>
    <div class="row g-3"><div class="col-md-6"><h3 class="h6">Personal details</h3><p>{{ $seller->seller_name }}<br>{{ $seller->email }} · {{ $seller->mobile_number }}<br>{{ $seller->shop_address }}, {{ $seller->city }}, {{ $seller->state }} {{ $seller->pincode }}</p></div><div class="col-md-6"><h3 class="h6">Business details</h3><p>{{ $seller->shop_name }}<br>{{ $seller->business_type ?: 'Not provided' }}<br>GST: {{ $seller->gst_number ?: 'Not provided' }}<br>Udyam: {{ $seller->udyam_number ?: 'Not provided' }}</p></div><div class="col-md-6"><h3 class="h6">KYC & shop verification</h3><p>PAN: {{ $seller->pan_number ? substr($seller->pan_number,0,5).'****'.substr($seller->pan_number,-1) : 'Not provided' }}<br>Aadhaar: {{ $seller->aadhaar_verified_at ? 'Verified' : ($seller->aadhaar_document_path ? 'Document uploaded' : 'Missing') }}<br>Certificate: {{ $seller->business_certificate_path ? 'Uploaded' : 'Missing' }}<br>Shop proof: {{ $seller->shop_proof_path ? 'Uploaded' : 'Missing' }}</p></div><div class="col-md-6"><h3 class="h6">Bank details</h3><p>{{ $seller->bank_account_holder ?: 'Not provided' }}<br>Account: {{ $seller->bank_account_number ? 'XXXX XXXX '.substr($seller->bank_account_number,-4) : 'Not provided' }}<br>{{ $seller->bank_ifsc ?: 'IFSC not provided' }} · {{ $seller->bank_name ?: 'Bank not provided' }}<br>Proof: {{ $seller->bank_proof_path ? 'Uploaded' : 'Missing' }}</p></div></div>
    <a class="btn btn-primary" href="{{ route('seller.application.review') }}">Review application</a>
</x-seller-verification.layout>
